#!/usr/bin/env python3
import subprocess
import sys
from pathlib import Path
from datetime import datetime

# -------------------- USER CONFIG (edit if needed) --------------------
# Python interpreter used for the sub-processes (the one running this script)
PYTHON = sys.executable

# Common data paths
IMAGES_DIR      = r"data/images"
ANGLES_JSON     = r"data/angles.json"
SPLIT_JSON      = r"config/splits/subject_split.json"

# Predicted masks per seed (already generated by your segmentation model)
PRED_MASKS_DIRS = {
    42:   r"preds/seg_resnet34_42",
    2025: r"preds/seg_resnet34_2025",
    1337: r"preds/seg_resnet34_1337",
}

# Where to write outputs (models, logs, metrics). A subfolder per (mode, seed) will be created.
OUT_BASE = r"runsv8"

# Training hyperparameters (same for all runs; adjust if needed)
EPOCHS      = "100"
BATCH_SIZE  = "32"
LR          = "3e-4"
WD          = "1e-4"
NUM_BINS    = "72"   # use 72 bins to match your prior experiments
USE_AMP     = False  # set True to enable mixed precision training

# Modes and seeds to sweep
MODES = ["cls", "reg", "both"]
SEEDS = [42, 2025, 1337]
# ---------------------------------------------------------------------

def now():
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")

def run(cmd_list):
    print(f"[{now()}] Running:\n  ", " ".join(cmd_list), flush=True)
    # On Windows, pass list to avoid shell quoting issues
    subprocess.run(cmd_list, check=True)

def main():
    # Ensure OUT_BASE exists
    Path(OUT_BASE).mkdir(parents=True, exist_ok=True)

    total_jobs = 0
    for mode in MODES:
        for seed in SEEDS:
            pred_masks = PRED_MASKS_DIRS[seed]
            outdir = f"{OUT_BASE}/rot_{mode}_resnet18_{seed}"
            Path(outdir).mkdir(parents=True, exist_ok=True)

            # ------------------ TRAIN ------------------
            train_cmd = [
                PYTHON, "-m", "src.train_rot",
                "--mode", mode,
                "--images_dir", IMAGES_DIR,
                "--angles_json", ANGLES_JSON,
                "--pred_masks_dir", pred_masks,
                "--split_json", SPLIT_JSON,
                "--seed", str(seed),
                "--epochs", EPOCHS,
                "--batch_size", BATCH_SIZE,
                "--lr", LR,
                "--wd", WD,
                "--num_bins", NUM_BINS,
                "--outdir", outdir,
            ]
            if USE_AMP:
                train_cmd.append("--amp")

            run(train_cmd)
            total_jobs += 1

            # ------------------ EVAL -------------------
            ckpt = f"{outdir}/best.pt"
            eval_cmd = [
                PYTHON, "-m", "src.eval_rot",
                "--ckpt", ckpt,
                "--mode", mode,
                "--images_dir", IMAGES_DIR,
                "--angles_json", ANGLES_JSON,
                "--pred_masks_dir", pred_masks,
                "--split_json", SPLIT_JSON,
                "--seed", str(seed),
                "--num_bins", NUM_BINS,
                "--outdir", outdir,
            ]

            run(eval_cmd)
            total_jobs += 1

    print(f"[{now()}] All done. Jobs executed: {total_jobs}")

if __name__ == "__main__":
    try:
        main()
    except subprocess.CalledProcessError as e:
        print("\nERROR: A command failed with a non-zero exit status.", file=sys.stderr)
        print("Command that failed:", e.cmd, file=sys.stderr)
        print("Exit code:", e.returncode, file=sys.stderr)
        sys.exit(e.returncode)
    except KeyboardInterrupt:
        print("\nInterrupted by user.", file=sys.stderr)
        sys.exit(130)
